void assert_process_queue_equal(struct node *actual, struct node *expected) {
    struct node *actual_ptr = actual;
    struct node *expected_ptr = expected;
    while (actual_ptr != NULL && expected_ptr != NULL) {
        TEST_ASSERT_EQUAL(expected_ptr->ID, actual_ptr->ID);
        TEST_ASSERT_EQUAL(expected_ptr->AT, actual_ptr->AT);
